class Solution {
public:
    int findTheWinner(int n, int k) {
        int ans = 0;
        for (int i = 2; i <= n; ++i) {
            ans = (ans + k) % i;
        }
        return ans + 1;
    }
};

class Solution {
    public int findTheWinner(int n, int k) {
        int ans = 0;
        for (int i = 2; i <= n; ++i) {
            ans = (ans + k) % i;
        }
        return ans + 1;
    }
}

/**
 * @param {number} n
 * @param {number} k
 * @return {number}
